contracts/NawaUSDTVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {ERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

/// @title Nawa USDT Vault
/// @notice Share-based USDT yield vault. Capital is deployed off-chain into a
///         curated private-credit strategy; the contract is a non-custodial
///         router and escrow that holds funds only transiently under fixed rules.
///
///         Accounting is oracle-priced: an aumUpdater reports the off-chain
///         assets backing outstanding shares (`latestAum`). Value accrues to the
///         share price, not the balance, so the share token is a standard ERC20.
///
///         Redemptions are asynchronous: requestRedeem (burn) -> approve (set
///         final amount, enqueue) -> fund (from deposit netting or the backstop)
///         -> claim. A deposit nets its inflow against the oldest approved-unfunded
///         redemptions before forwarding the surplus to the strategy.
///
///         Deployed behind a UUPS proxy. Upgrades are gated to `upgrader`, which is
///         expected to be a TimelockController so an upgrade is announced on-chain
///         and delayed before it can take effect.
contract NawaUSDTVault is
    Initializable,
    ERC20Upgradeable,
    ReentrancyGuardUpgradeable,
    PausableUpgradeable,
    UUPSUpgradeable
{
    using SafeERC20 for IERC20;

    // --- constants ---

    /// @dev Price-per-share fixed-point scale, independent of token decimals.
    uint256 private constant PPS_SCALE = 1e18;

    /// @dev Virtual share/asset offset. Because `latestAum` is tracked in storage
    ///      (never read from `asset.balanceOf`), a direct USDT donation cannot move
    ///      the share price, so the classic ERC4626 inflation attack is structurally
    ///      blocked. The +1/+1 offset additionally hardens the first-deposit rounding.
    uint256 private constant VIRTUAL_SHARES = 1;
    uint256 private constant VIRTUAL_ASSETS = 1;

    uint256 private constant BPS_DENOMINATOR = 10_000;
    uint256 private constant MAX_AUM_CHANGE_LIMIT_BPS = 5_000; // 50%
    uint256 private constant MAX_AUM_UPDATE_COOLDOWN = 7 days;
    uint256 private constant MAX_SETTLEMENT_WINDOW = 180 days;
    uint256 private constant MAX_AUM_AGE = 30 days;
    uint256 private constant OUTFLOW_FREEZE_DURATION = 48 hours;
    uint256 private constant OVERRIDE_NAV_DEVIATION_CEILING_BPS = 1_000; // 10%

    uint8 private constant SHARE_DECIMALS = 6;

    // --- redemption queue ---

    enum Status {
        None,
        Pending,
        Approved,
        Funded,
        Rejected,
        Cancelled,
        Settled
    }

    struct RedemptionRequest {
        address user;
        uint256 shares; // shares burned for this request
        uint256 assetAmount; // current settlement payout (may be overridden at approval)
        uint256 outstanding; // assetAmount minus funded so far; 0 once fully funded
        uint256 originalPps; // price-per-share snapshot at request time (PPS_SCALE)
        uint256 overridePps; // 0 if no override applied
        uint256 requestedAt; // timestamp; basis for the settlement SLA
        uint256 cancelAfter; // deadline fixed at request time; a later window change cannot move it
        Status status;
    }

    // --- asset ---

    // Set once in initialize. Treat as upgrade-immutable: a future upgrade must
    // never add a setter, as repointing the asset would corrupt all accounting.
    IERC20 public asset;

    // --- roles ---

    address public admin; // Nawa, day-to-day operator
    address public pendingAdmin;
    address public fundsManagerAssigner; // multisig: the ONLY caller of setFundsManager
    address public fundsManager; // curator deployment address (receives surplus)
    address public redeemManager; // hot key: approves/rejects requests
    address public aumUpdater; // oracle: reports off-chain AUM
    address public pauser; // can pause but cannot move funds
    address public backstop; // multisig: funds the queue from recycled strategy liquidity
    address public upgrader; // authorized to upgrade the implementation (TimelockController)
    address public guardian; // multisig: can freeze outflows briefly in an incident

    // --- accounting ---

    uint256 public latestAum; // assets backing outstanding shares
    uint256 public pendingRedemptionAum; // assets committed to burned-but-unfunded redemptions
    uint256 public approvedOutstanding; // still-unfunded value across Approved requests
    uint256 public totalClaimable; // sum of unclaimed `claimable` balances
    uint256 public mintingCap; // max share totalSupply via deposits

    mapping(address => uint256) public claimable; // pull-over-push payout ledger

    // --- redemption queue state ---

    mapping(uint256 => RedemptionRequest) private _requests;
    uint256 public requestCounter; // next request id

    // Funding queue: a FIFO of *approved* request ids awaiting cash. Approval
    // enqueues; funding drains from the head. Keeping it separate from the request
    // log means an unapproved (Pending) request can never block funding of approved
    // ones behind it.
    mapping(uint256 => uint256) private _fundingQueue; // position => request id
    uint256 public fundingHead; // next position to fund
    uint256 public fundingTail; // next position to enqueue
    uint256 public maxNettingIterations; // gas bound on the funding loop

    // --- guardrails / limits ---

    uint256 public aumChangeLimitBps; // max per-share |delta| per AUM update
    uint256 public aumUpdateCooldownSecs; // min gap between AUM updates
    uint256 public lastAumUpdateAt;
    uint256 public lastNavAffectingBlock; // last block that changed supply or latestAum outside updateAum
    uint256 public maxAumAge; // max report age for price-sensitive entry/exit paths
    uint256 public outflowsFrozenUntil; // guardian circuit breaker on exit/funding paths
    uint256 public overrideNavMaxDeviationBps; // cap on approval override vs request-time NAV

    uint256 public minDeposit; // in asset units (6 decimals)
    uint256 public minRedeemShares; // in share units
    uint256 public maxSettlementWindow; // SLA: requests should be funded within this window

    // --- events ---

    event Deposited(address indexed user, uint256 assets, uint256 shares, uint256 forwardedToStrategy);
    event RedemptionRequested(uint256 indexed id, address indexed user, uint256 shares, uint256 assetAmount);
    event RedemptionApproved(
        uint256 indexed id, address indexed user, uint256 assetAmount, uint256 originalPps, uint256 overridePps
    );
    event RedemptionRejected(uint256 indexed id, address indexed user, uint256 shares);
    event RedemptionCancelled(uint256 indexed id, address indexed user, uint256 shares);
    event RedemptionSettled(uint256 indexed id, address indexed user, uint256 amount);
    event RedemptionFunded(uint256 indexed id, address indexed user, uint256 amount, bool fullyFunded);
    event Claimed(address indexed user, uint256 amount);
    /// @dev totalFunded counts everything credited to the queue in this call,
    ///      including idle balance that was already in the contract, so it can
    ///      legitimately exceed amountIn. Off-chain accounting of the backstop's
    ///      own contribution must sum amountIn, never totalFunded.
    event BackstopFunded(address indexed from, uint256 amountIn, uint256 totalFunded);
    event SurplusSwept(address indexed to, uint256 amount);
    event AumUpdated(uint256 oldAum, uint256 newAum, uint256 newPricePerShare);

    event FundsManagerChanged(address indexed previous, address indexed current);
    event FundsManagerAssignerChanged(address indexed previous, address indexed current);
    event RedeemManagerChanged(address indexed previous, address indexed current);
    event AumUpdaterChanged(address indexed previous, address indexed current);
    event PauserChanged(address indexed previous, address indexed current);
    event BackstopChanged(address indexed previous, address indexed current);
    event UpgraderChanged(address indexed previous, address indexed current);
    event GuardianChanged(address indexed previous, address indexed current);
    event OutflowsFrozen(address indexed by, uint256 until);
    event OutflowsUnfrozen(address indexed by);
    event SharesBurned(address indexed from, uint256 shares);
    event AdminTransferStarted(address indexed previous, address indexed pending);
    event AdminTransferred(address indexed previous, address indexed current);
    event ParameterChanged(bytes32 indexed key, uint256 value);

    // --- errors ---

    error NotAuthorized();
    error ZeroAddress();
    error ZeroAmount();
    error BelowMinimum();
    error MintingCapExceeded();
    error InvalidStatus();
    error CooldownActive();
    error ChangeLimitExceeded();
    error DeviationTooHigh();
    error ParameterOutOfRange();
    error FundsManagerUnset();
    error NothingToClaim();
    error AumUnderflow();
    error SettlementWindowNotElapsed();
    error WouldZeroAum();
    error RecoveryRequired();
    error StaleReport();
    error StaleNav();
    error PendingFullExit();
    error RepriceWhilePaused();
    error Expired();
    error SlippageExceeded();
    error OutflowFreezeActive();

    // --- modifiers ---

    modifier onlyAdmin() {
        if (msg.sender != admin) revert NotAuthorized();
        _;
    }

    modifier onlyRedeemManager() {
        if (msg.sender != redeemManager) revert NotAuthorized();
        _;
    }

    /// @dev Guardian circuit breaker on the paths that move USDT out or credit
    ///      claimable. Distinct from pause: pause is the soft halt that stops
    ///      entry and pricing while the queue winds down; this stops the wind-down
    ///      itself when something already credited money in error. Time-bounded so
    ///      it can never become a permanent freeze of user funds.
    modifier whenOutflowsNotFrozen() {
        if (block.timestamp < outflowsFrozenUntil) revert OutflowFreezeActive();
        _;
    }

    struct InitParams {
        IERC20 asset;
        address admin;
        address fundsManagerAssigner;
        address fundsManager;
        address redeemManager;
        address aumUpdater;
        address pauser;
        address backstop;
        address upgrader;
        address guardian;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(InitParams memory p) external initializer {
        if (
            address(p.asset) == address(0) ||
            p.admin == address(0) ||
            p.fundsManagerAssigner == address(0) ||
            p.redeemManager == address(0) ||
            p.aumUpdater == address(0) ||
            p.pauser == address(0) ||
            p.backstop == address(0) ||
            p.upgrader == address(0) ||
            p.guardian == address(0)
        ) revert ZeroAddress();

        __ERC20_init("Nawa USDT Vault", "nzUSDT");
        __ReentrancyGuard_init();
        __Pausable_init();
        __UUPSUpgradeable_init();

        asset = p.asset;
        admin = p.admin;
        fundsManagerAssigner = p.fundsManagerAssigner;
        fundsManager = p.fundsManager; // may be set later by the assigner
        redeemManager = p.redeemManager;
        aumUpdater = p.aumUpdater;
        pauser = p.pauser;
        backstop = p.backstop;
        upgrader = p.upgrader;
        guardian = p.guardian;

        // defaults
        aumChangeLimitBps = 200; // 2% per update
        aumUpdateCooldownSecs = 1 days;
        maxAumAge = 7 days;
        overrideNavMaxDeviationBps = 200; // 2%
        lastAumUpdateAt = block.timestamp;

        minDeposit = 100 * (10 ** SHARE_DECIMALS); // 100 USDT
        minRedeemShares = 1 * (10 ** SHARE_DECIMALS); // 1 share
        maxSettlementWindow = 120 days;
        maxNettingIterations = 50;
        mintingCap = type(uint256).max;

        // Log the initial configuration so indexers can rebuild role and
        // parameter history from events alone, not only from later changes.
        emit AdminTransferred(address(0), p.admin);
        emit FundsManagerAssignerChanged(address(0), p.fundsManagerAssigner);
        if (p.fundsManager != address(0)) emit FundsManagerChanged(address(0), p.fundsManager);
        emit RedeemManagerChanged(address(0), p.redeemManager);
        emit AumUpdaterChanged(address(0), p.aumUpdater);
        emit PauserChanged(address(0), p.pauser);
        emit BackstopChanged(address(0), p.backstop);
        emit UpgraderChanged(address(0), p.upgrader);
        emit GuardianChanged(address(0), p.guardian);
        emit ParameterChanged("aumChangeLimitBps", aumChangeLimitBps);
        emit ParameterChanged("aumUpdateCooldownSecs", aumUpdateCooldownSecs);
        emit ParameterChanged("maxAumAge", maxAumAge);
        emit ParameterChanged("overrideNavMaxDeviationBps", overrideNavMaxDeviationBps);
        emit ParameterChanged("minDeposit", minDeposit);
        emit ParameterChanged("minRedeemShares", minRedeemShares);
        emit ParameterChanged("maxSettlementWindow", maxSettlementWindow);
        emit ParameterChanged("maxNettingIterations", maxNettingIterations);
        emit ParameterChanged("mintingCap", mintingCap);
    }

    function decimals() public pure override returns (uint8) {
        return SHARE_DECIMALS;
    }

    /// @dev UUPS upgrade gate. `upgrader` is expected to be a TimelockController,
    ///      so an upgrade is queued publicly and can only execute after its delay.
    function _authorizeUpgrade(address) internal view override {
        if (msg.sender != upgrader) revert NotAuthorized();
    }

    // --- user flows ---

    /// @notice Deposit USDT, mint shares at the current price, net the inflow
    ///         against the oldest approved-unfunded redemptions, and forward the
    ///         surplus to the strategy. Executes at the stored NAV at inclusion
    ///         time, whatever it is; use depositWithMinShares to bound it.
    function deposit(uint256 amount) external nonReentrant whenNotPaused returns (uint256 shares) {
        shares = _deposit(amount);
    }

    /// @notice deposit with execution bounds: reverts if the transaction lands
    ///         after `deadline` or mints fewer than `minSharesOut`, so an oracle
    ///         update between signing and inclusion cannot worsen the fill.
    function depositWithMinShares(
        uint256 amount,
        uint256 minSharesOut,
        uint256 deadline
    ) external nonReentrant whenNotPaused returns (uint256 shares) {
        if (block.timestamp > deadline) revert Expired();
        shares = _deposit(amount);
        if (shares < minSharesOut) revert SlippageExceeded();
    }

    function _deposit(uint256 amount) private returns (uint256 shares) {
        if (amount < minDeposit) revert BelowMinimum();
        // An empty vault bootstraps at pps 1.0 with no price to protect, so a
        // stale report must not block it; the oracle may simply not be live yet.
        if (totalSupply() > 0 && block.timestamp > lastAumUpdateAt + maxAumAge) revert StaleNav();
        // Zero AUM with live shares is a corrupted pricing state (the guards in
        // requestRedeem, _applyOverride and updateAum keep it unreachable); refuse
        // to price against it rather than mint at a near-zero share price.
        if (latestAum == 0 && totalSupply() > 0) revert RecoveryRequired();
        // Do not bootstrap at pps 1.0 while a full-supply redemption is still
        // unsettled: a later reject or cancel re-mints those shares at their old
        // price and dilutes everyone who entered in between. Deposits reopen once
        // the exit is funded, settled, rejected or cancelled.
        if (totalSupply() == 0 && pendingRedemptionAum > 0) revert PendingFullExit();

        asset.safeTransferFrom(msg.sender, address(this), amount);

        // Price against pre-deposit state.
        shares = _convertToShares(amount);
        if (shares == 0) revert ZeroAmount();
        if (totalSupply() + shares > mintingCap) revert MintingCapExceeded();

        _mint(msg.sender, shares);
        latestAum += amount;
        lastNavAffectingBlock = block.number;

        // Fund the queue from this inflow (pull-over-push: credit claimable only).
        uint256 consumed = _fundQueue(amount, maxNettingIterations);
        uint256 surplus = amount - consumed;

        // Forward the surplus only when no approved request is still owed money.
        // If approved requests remain (the iteration bound stopped us short), keep
        // the surplus idle so processQueue can fund it, rather than shipping cash
        // owed to an exiting redeemer off-chain to the strategy.
        if (surplus > 0 && !_hasApprovedUnfunded()) {
            if (fundsManager == address(0)) revert FundsManagerUnset();
            asset.safeTransfer(fundsManager, surplus);
        } else {
            surplus = 0;
        }

        emit Deposited(msg.sender, amount, shares, surplus);
    }

    /// @notice Burn shares to queue a redemption. The payout is priced and locked
    ///         at request time; later NAV moves do not change it (approval may
    ///         still apply a bounded override). Executes at the stored NAV at
    ///         inclusion time; use requestRedeemWithMinAssets to bound it.
    function requestRedeem(uint256 shares) external nonReentrant whenNotPaused returns (uint256 id) {
        (id, ) = _requestRedeem(shares);
    }

    /// @notice requestRedeem with execution bounds on the locked amount: reverts
    ///         if the transaction lands after `deadline` or locks less than
    ///         `minAssetsOut`. The bound covers request-time pricing only; the
    ///         final payout can still move within the approval override cap.
    function requestRedeemWithMinAssets(
        uint256 shares,
        uint256 minAssetsOut,
        uint256 deadline
    ) external nonReentrant whenNotPaused returns (uint256 id) {
        if (block.timestamp > deadline) revert Expired();
        uint256 assetAmount;
        (id, assetAmount) = _requestRedeem(shares);
        if (assetAmount < minAssetsOut) revert SlippageExceeded();
    }

    function _requestRedeem(uint256 shares) private returns (uint256 id, uint256 assetAmount) {
        if (shares < minRedeemShares) revert BelowMinimum();
        if (block.timestamp > lastAumUpdateAt + maxAumAge) revert StaleNav();
        if (latestAum == 0 && totalSupply() > 0) revert RecoveryRequired();

        assetAmount = _convertToAssets(shares);
        if (assetAmount == 0) revert ZeroAmount();
        // A partial redemption must never drain latestAum to zero while shares
        // remain: that state skips the AUM change-limit and corrupts deposit
        // pricing. Rounding can push assetAmount up to the full latestAum in a
        // deep-loss book, so reject and let the user redeem in full instead.
        if (shares < totalSupply() && assetAmount >= latestAum) revert WouldZeroAum();
        uint256 pps = _pricePerShare();

        _burn(msg.sender, shares);

        latestAum -= assetAmount;
        pendingRedemptionAum += assetAmount;
        lastNavAffectingBlock = block.number;

        // When the last holder exits, clear the rounding dust so the vault
        // re-bootstraps at pps 1.0 on the next deposit.
        if (totalSupply() == 0) latestAum = 0;

        id = requestCounter++;
        _requests[id] = RedemptionRequest({
            user: msg.sender,
            shares: shares,
            assetAmount: assetAmount,
            outstanding: assetAmount,
            originalPps: pps,
            overridePps: 0,
            requestedAt: block.timestamp,
            cancelAfter: block.timestamp + maxSettlementWindow,
            status: Status.Pending
        });

        emit RedemptionRequested(id, msg.sender, shares, assetAmount);
    }

    /// @notice Pull your own accrued payout. Remains callable while paused so a halt
    ///         cannot trap funded redeemers; only the time-bounded guardian outflow
    ///         freeze can defer it.
    function claim() external nonReentrant whenOutflowsNotFrozen returns (uint256) {
        return _claim(msg.sender);
    }

    /// @notice Push a user's accrued payout to them. Permissionless: it can only ever
    ///         send `claimable[user]` to `user`, so a keeper (or anyone) can settle on
    ///         their behalf and the user never has to claim. Paying one user at a time
    ///         keeps a frozen recipient from blocking others.
    function claimFor(address user) external nonReentrant whenOutflowsNotFrozen returns (uint256) {
        return _claim(user);
    }

    function _claim(address user) private returns (uint256 amount) {
        amount = claimable[user];
        if (amount == 0) revert NothingToClaim();

        claimable[user] = 0;
        totalClaimable -= amount;

        asset.safeTransfer(user, amount);
        emit Claimed(user, amount);
    }

    /// @notice Permissionless. Push the funding queue forward using USDT already
    ///         idle in the contract (netting surplus left by the iteration bound,
    ///         or funds returned via the backstop).
    function processQueue(uint256 maxIterations) external nonReentrant whenOutflowsNotFrozen {
        uint256 available = _idleFundable();
        if (available == 0) return;
        _fundQueue(available, maxIterations);
    }

    // --- redeem manager ---

    /// @dev Optional re-pricing shared by approveRequest / approveAndPay. Moves the
    ///      difference between shareholders (latestAum) and the redemption liability
    ///      (pendingRedemptionAum), bounded by overrideNavMaxDeviationBps.
    function _applyOverride(RedemptionRequest storage r, uint256 overridePps) private {
        if (overridePps == 0 || overridePps == r.originalPps) return;
        // Approval stays callable while paused so the queue can wind down, but an
        // actual reprice moves latestAum, and with entry and exit frozen no holder
        // can react to it. Winding the queue down never requires moving the price.
        if (paused()) revert RepriceWhilePaused();
        if (_deviationBps(overridePps, r.originalPps) > overrideNavMaxDeviationBps) revert DeviationTooHigh();

        uint256 newAmount = Math.mulDiv(r.shares, overridePps, PPS_SCALE);
        if (newAmount == 0) revert ZeroAmount();

        uint256 oldAmount = r.assetAmount;
        if (newAmount > oldAmount) {
            uint256 delta = newAmount - oldAmount;
            // >=: an override must never drain latestAum to zero while shares
            // remain outstanding (see the invariant note in requestRedeem).
            if (delta >= latestAum) revert AumUnderflow();
            latestAum -= delta;
            pendingRedemptionAum += delta;
        } else if (newAmount < oldAmount) {
            uint256 delta = oldAmount - newAmount;
            latestAum += delta;
            pendingRedemptionAum -= delta;
            // A down-override on the last holder's exit returns value to a book
            // with no shareholders left. Clear it like the request path does, or
            // the orphaned amount would corrupt the next bootstrap price.
            if (totalSupply() == 0) latestAum = 0;
        }

        r.assetAmount = newAmount;
        r.outstanding = newAmount;
        r.overridePps = overridePps;
        lastNavAffectingBlock = block.number;
    }

    /// @notice Validate a request, finalise its payout, and enqueue it for funding
    ///         (deposit netting / backstop). Moves no cash. Callable while paused so
    ///         the backstop can wind down.
    /// @param overridePps optional corrected price-per-share (PPS_SCALE). 0 to keep
    ///        the request-time price. Bounded by overrideNavMaxDeviationBps.
    function approveRequest(uint256 id, uint256 overridePps) external onlyRedeemManager {
        RedemptionRequest storage r = _requests[id];
        if (r.status != Status.Pending) revert InvalidStatus();

        _applyOverride(r, overridePps);

        r.status = Status.Approved;
        approvedOutstanding += r.outstanding;
        _fundingQueue[fundingTail++] = id;

        emit RedemptionApproved(id, r.user, r.assetAmount, r.originalPps, r.overridePps);
    }

    /// @notice Approve and pay a Pending request directly in one step: the redeem
    ///         manager sends the exact payout to the user now, instead of routing it
    ///         through netting/backstop and a later claim. The caller funds it (from
    ///         recycled strategy liquidity) and must have approved the vault to pull
    ///         the payout. A frozen recipient only fails their own settlement.
    function approveAndPay(
        uint256 id,
        uint256 overridePps
    ) external onlyRedeemManager nonReentrant whenOutflowsNotFrozen {
        RedemptionRequest storage r = _requests[id];
        if (r.status != Status.Pending) revert InvalidStatus();

        _applyOverride(r, overridePps);

        uint256 payout = r.assetAmount;
        r.outstanding = 0;
        r.status = Status.Settled;
        pendingRedemptionAum -= payout;

        emit RedemptionApproved(id, r.user, payout, r.originalPps, r.overridePps);
        asset.safeTransferFrom(msg.sender, r.user, payout);
        emit RedemptionSettled(id, r.user, payout);
    }

    /// @notice Settle an already-Approved request directly, paying the caller's USDT
    ///         to the user for the still-outstanding amount (an approved request may
    ///         be partially funded already; the funded part stays claimable). No
    ///         re-price — the amount was finalized at approval. Its funding-queue slot
    ///         is left in place and lazily skipped by `_fundQueue` once settled.
    function payApproved(uint256 id) external onlyRedeemManager nonReentrant whenOutflowsNotFrozen {
        RedemptionRequest storage r = _requests[id];
        if (r.status != Status.Approved) revert InvalidStatus();

        uint256 payout = r.outstanding;
        if (payout == 0) revert ZeroAmount();
        r.outstanding = 0;
        r.status = Status.Settled;
        pendingRedemptionAum -= payout;
        approvedOutstanding -= payout;

        asset.safeTransferFrom(msg.sender, r.user, payout);
        emit RedemptionSettled(id, r.user, payout);
    }

    /// @notice Reject a still-Pending request, returning the user's shares and
    ///         reversing the request-time accounting. Re-mint intentionally bypasses
    ///         mintingCap: it reverses a prior burn, not a new subscription.
    function rejectRequest(uint256 id) external {
        if (msg.sender != redeemManager && msg.sender != admin) revert NotAuthorized();

        RedemptionRequest storage r = _requests[id];
        if (r.status != Status.Pending) revert InvalidStatus();

        r.status = Status.Rejected;
        r.outstanding = 0;
        latestAum += r.assetAmount;
        pendingRedemptionAum -= r.assetAmount;
        lastNavAffectingBlock = block.number;
        _mint(r.user, r.shares);

        emit RedemptionRejected(id, r.user, r.shares);
    }

    /// @notice User escape hatch: cancel your own still-Pending request once the
    ///         settlement window has elapsed, reclaiming your burned shares. Gives
    ///         redeemers on-chain recourse if the operator never approves. Only
    ///         Pending requests qualify (an approved request is already queued for
    ///         funding); the re-mint reverses a burn, so it bypasses mintingCap.
    function cancelRequest(uint256 id) external nonReentrant {
        RedemptionRequest storage r = _requests[id];
        if (r.user != msg.sender) revert NotAuthorized();
        if (r.status != Status.Pending) revert InvalidStatus();
        if (block.timestamp <= r.cancelAfter) revert SettlementWindowNotElapsed();

        r.status = Status.Cancelled;
        r.outstanding = 0;
        latestAum += r.assetAmount;
        pendingRedemptionAum -= r.assetAmount;
        lastNavAffectingBlock = block.number;
        _mint(r.user, r.shares);

        emit RedemptionCancelled(id, r.user, r.shares);
    }

    // --- backstop (multisig) ---

    /// @notice Pull recycled strategy liquidity into the contract and fund the
    ///         queue. The slow-path source when deposit inflow is insufficient.
    ///         Callable while paused for emergency wind-down, but subject to the
    ///         guardian outflow freeze.
    function fundFromBackstop(
        uint256 amount,
        uint256 maxIterations
    ) external nonReentrant whenOutflowsNotFrozen {
        if (msg.sender != backstop) revert NotAuthorized();
        if (amount == 0) revert ZeroAmount();

        asset.safeTransferFrom(msg.sender, address(this), amount);
        // Fund from the whole idle balance, not just this transfer: stranded
        // netting surplus should reach the queue in the same call.
        uint256 totalFunded = _fundQueue(_idleFundable(), maxIterations);

        emit BackstopFunded(msg.sender, amount, totalFunded);
    }

    // --- oracle (aumUpdater) ---

    /// @notice Report the off-chain assets backing outstanding shares, NET of any
    ///         performance fee and excluding pendingRedemptionAum. Fees are taken
    ///         off-chain before reporting; the contract charges no fee of its own.
    /// @param snapshotBlock the block whose on-chain state the report was computed
    ///        against. A deposit, redemption request, override, reject or cancel
    ///        landing after that block invalidates the report: the absolute value
    ///        would silently revert their accounting. Recompute and resubmit.
    function updateAum(uint256 newAum, uint256 snapshotBlock) external whenNotPaused {
        if (msg.sender != aumUpdater) revert NotAuthorized();
        if (block.timestamp < lastAumUpdateAt + aumUpdateCooldownSecs) revert CooldownActive();
        if (snapshotBlock > block.number || snapshotBlock < lastNavAffectingBlock) revert StaleReport();

        uint256 supply = totalSupply();
        uint256 oldAum = latestAum;

        // An empty vault backs nothing: force AUM to zero regardless of the report,
        // so no update can price an arbitrary bootstrap and the next deposit starts
        // at pps 1.0. The change-limit is meaningless with no shares. A zero report
        // is accepted here: zero is the true value of an empty vault.
        if (supply == 0) {
            latestAum = 0;
            lastAumUpdateAt = block.timestamp;
            emit AumUpdated(oldAum, 0, PPS_SCALE);
            return;
        }

        // With shares outstanding, a zero report cannot be priced through the
        // change-limit path; a true total loss is an incident handled by pause
        // and governance, not an ordinary oracle report.
        if (newAum == 0) revert ZeroAmount();

        // Zero AUM with live shares would let this report skip the change-limit
        // and set an arbitrary price. Unreachable while the request, override and
        // deposit guards hold; if it ever occurs, recovery goes through governance.
        if (oldAum == 0) revert RecoveryRequired();

        // Bound the per-share price move, not the raw AUM, so the cap is unaffected
        // by how much of the book is mid-redemption.
        uint256 oldPps = Math.mulDiv(oldAum + VIRTUAL_ASSETS, PPS_SCALE, supply + VIRTUAL_SHARES);
        // A price that floors to zero (supply vastly larger than AUM) cannot anchor
        // the deviation check; treat it like the zero-AUM state above.
        if (oldPps == 0) revert RecoveryRequired();
        uint256 candidatePps = Math.mulDiv(newAum + VIRTUAL_ASSETS, PPS_SCALE, supply + VIRTUAL_SHARES);
        if (_deviationBps(candidatePps, oldPps) > aumChangeLimitBps) revert ChangeLimitExceeded();

        latestAum = newAum;
        lastAumUpdateAt = block.timestamp;

        emit AumUpdated(oldAum, newAum, Math.mulDiv(newAum + VIRTUAL_ASSETS, PPS_SCALE, supply + VIRTUAL_SHARES));
    }

    // --- multisig: fundsManager ---

    /// @notice Set where deposit surplus is sent. Exclusive to the assigner
    ///         multisig; the Nawa admin cannot call this.
    function setFundsManager(address newFundsManager) external {
        if (msg.sender != fundsManagerAssigner) revert NotAuthorized();
        if (newFundsManager == address(0)) revert ZeroAddress();
        if (newFundsManager == fundsManager) return;
        emit FundsManagerChanged(fundsManager, newFundsManager);
        fundsManager = newFundsManager;
    }

    /// @notice Rotate the assigner. Only the current assigner can do this, so the
    ///         gate cannot be repointed by the admin.
    function setFundsManagerAssigner(address newAssigner) external {
        if (msg.sender != fundsManagerAssigner) revert NotAuthorized();
        if (newAssigner == address(0)) revert ZeroAddress();
        if (newAssigner == fundsManagerAssigner) return;
        emit FundsManagerAssignerChanged(fundsManagerAssigner, newAssigner);
        fundsManagerAssigner = newAssigner;
    }

    /// @notice Governance remedy for shares that exist in error (a bug, a bad
    ///         report, an operational mistake): burn them from the named holder so
    ///         the dilution of everyone else is reversed. Gated to `upgrader`, the
    ///         same timelock that controls upgrades, so use is announced on-chain
    ///         and delayed; it can never be a fast or quiet action.
    function burnSharesFrom(address from, uint256 shares) external {
        if (msg.sender != upgrader) revert NotAuthorized();
        _burn(from, shares);
        // If governance removes the last shares, nothing is backed anymore;
        // clear the book like a full exit so the next deposit boots at pps 1.0.
        if (totalSupply() == 0) latestAum = 0;
        lastNavAffectingBlock = block.number;
        emit SharesBurned(from, shares);
    }

    /// @notice Rotate the upgrade authority. Only the current upgrader can call it,
    ///         so the change is itself subject to the timelock delay. Used for key
    ///         rotation or repointing the proxy at a new authority.
    function setUpgrader(address newUpgrader) external {
        if (msg.sender != upgrader) revert NotAuthorized();
        if (newUpgrader == address(0)) revert ZeroAddress();
        if (newUpgrader == upgrader) return;
        emit UpgraderChanged(upgrader, newUpgrader);
        upgrader = newUpgrader;
    }

    // --- admin (Nawa) ---

    /// @notice Forward genuinely surplus idle USDT to the strategy. Cash needed to
    ///         cover in-flight redemptions is retained: the sendable amount is idle
    ///         minus the full redemption liability (`pendingRedemptionAum`), which
    ///         already counts every burned-share request, Pending or approved.
    function sweepToStrategy(uint256 amount) external onlyAdmin nonReentrant {
        if (fundsManager == address(0)) revert FundsManagerUnset();
        uint256 idle = _idleFundable();
        uint256 free = idle > pendingRedemptionAum ? idle - pendingRedemptionAum : 0;
        uint256 send = amount > free ? free : amount;
        if (send == 0) revert ZeroAmount();
        asset.safeTransfer(fundsManager, send);
        emit SurplusSwept(fundsManager, send);
    }

    function setRedeemManager(address a) external onlyAdmin {
        if (a == address(0)) revert ZeroAddress();
        if (a == redeemManager) return;
        emit RedeemManagerChanged(redeemManager, a);
        redeemManager = a;
    }

    function setAumUpdater(address a) external onlyAdmin {
        if (a == address(0)) revert ZeroAddress();
        if (a == aumUpdater) return;
        emit AumUpdaterChanged(aumUpdater, a);
        aumUpdater = a;
    }

    function setPauser(address a) external onlyAdmin {
        if (a == address(0)) revert ZeroAddress();
        if (a == pauser) return;
        emit PauserChanged(pauser, a);
        pauser = a;
    }

    function setBackstop(address a) external onlyAdmin {
        if (a == address(0)) revert ZeroAddress();
        if (a == backstop) return;
        emit BackstopChanged(backstop, a);
        backstop = a;
    }

    function setAumChangeLimitBps(uint256 v) external onlyAdmin {
        if (v == 0 || v > MAX_AUM_CHANGE_LIMIT_BPS) revert ParameterOutOfRange();
        if (v == aumChangeLimitBps) return;
        aumChangeLimitBps = v;
        emit ParameterChanged("aumChangeLimitBps", v);
    }

    function setAumUpdateCooldown(uint256 v) external onlyAdmin {
        if (v > MAX_AUM_UPDATE_COOLDOWN) revert ParameterOutOfRange();
        if (v == aumUpdateCooldownSecs) return;
        aumUpdateCooldownSecs = v;
        emit ParameterChanged("aumUpdateCooldownSecs", v);
    }

    function setOverrideNavMaxDeviationBps(uint256 v) external onlyAdmin {
        if (v > OVERRIDE_NAV_DEVIATION_CEILING_BPS) revert ParameterOutOfRange();
        if (v == overrideNavMaxDeviationBps) return;
        overrideNavMaxDeviationBps = v;
        emit ParameterChanged("overrideNavMaxDeviationBps", v);
    }

    function setMaxAumAge(uint256 v) external onlyAdmin {
        if (v == 0 || v > MAX_AUM_AGE) revert ParameterOutOfRange();
        if (v == maxAumAge) return;
        maxAumAge = v;
        emit ParameterChanged("maxAumAge", v);
    }

    function setMinDeposit(uint256 v) external onlyAdmin {
        if (v == minDeposit) return;
        minDeposit = v;
        emit ParameterChanged("minDeposit", v);
    }

    function setMinRedeemShares(uint256 v) external onlyAdmin {
        if (v == 0) revert ParameterOutOfRange();
        if (v == minRedeemShares) return;
        minRedeemShares = v;
        emit ParameterChanged("minRedeemShares", v);
    }

    function setMintingCap(uint256 v) external onlyAdmin {
        if (v == mintingCap) return;
        mintingCap = v;
        emit ParameterChanged("mintingCap", v);
    }

    function setMaxSettlementWindow(uint256 v) external onlyAdmin {
        // Bounded so admin can't disable the cancelRequest escape hatch by pushing the
        // window arbitrarily far out (or overflowing requestedAt + window).
        if (v == 0 || v > MAX_SETTLEMENT_WINDOW) revert ParameterOutOfRange();
        if (v == maxSettlementWindow) return;
        maxSettlementWindow = v;
        emit ParameterChanged("maxSettlementWindow", v);
    }

    function setMaxNettingIterations(uint256 v) external onlyAdmin {
        if (v == 0) revert ParameterOutOfRange();
        if (v == maxNettingIterations) return;
        maxNettingIterations = v;
        emit ParameterChanged("maxNettingIterations", v);
    }

    function transferAdmin(address newAdmin) external onlyAdmin {
        if (newAdmin == address(0)) revert ZeroAddress();
        pendingAdmin = newAdmin;
        emit AdminTransferStarted(admin, newAdmin);
    }

    function acceptAdmin() external {
        if (msg.sender != pendingAdmin) revert NotAuthorized();
        emit AdminTransferred(admin, pendingAdmin);
        admin = pendingAdmin;
        pendingAdmin = address(0);
    }

    // --- pause (pauser) ---

    function pause() external {
        if (msg.sender != pauser && msg.sender != admin) revert NotAuthorized();
        _pause();
    }

    function unpause() external onlyAdmin {
        _unpause();
    }

    // --- outflow freeze (guardian) ---

    /// @notice Freeze claim, funding and direct-settlement paths for a fixed
    ///         48 hours, the reaction window when claimable was credited in error
    ///         (bad report or bug) and money is about to leave. Calling again
    ///         extends the window; admin can rotate a misbehaving guardian and
    ///         unfreeze, so the breaker cannot be held down forever.
    function freezeOutflows() external {
        if (msg.sender != guardian) revert NotAuthorized();
        outflowsFrozenUntil = block.timestamp + OUTFLOW_FREEZE_DURATION;
        emit OutflowsFrozen(msg.sender, outflowsFrozenUntil);
    }

    /// @notice Lift the freeze early once the incident is understood.
    function unfreezeOutflows() external {
        if (msg.sender != guardian && msg.sender != admin) revert NotAuthorized();
        outflowsFrozenUntil = 0;
        emit OutflowsUnfrozen(msg.sender);
    }

    function setGuardian(address a) external onlyAdmin {
        if (a == address(0)) revert ZeroAddress();
        if (a == guardian) return;
        emit GuardianChanged(guardian, a);
        guardian = a;
    }

    // --- views ---

    function pricePerShare() external view returns (uint256) {
        return _pricePerShare();
    }

    function previewDeposit(uint256 amount) external view returns (uint256) {
        return _convertToShares(amount);
    }

    function previewRedeem(uint256 shares) external view returns (uint256) {
        return _convertToAssets(shares);
    }

    function getRequest(uint256 id) external view returns (RedemptionRequest memory) {
        return _requests[id];
    }

    /// @notice True once a request has been outstanding longer than the SLA window
    ///         that was in force when it was made.
    function isRequestOverdue(uint256 id) external view returns (bool) {
        RedemptionRequest storage r = _requests[id];
        if (r.status != Status.Pending && r.status != Status.Approved) return false;
        return block.timestamp > r.cancelAfter;
    }

    // --- internal math ---

    function _convertToShares(uint256 amount) private view returns (uint256) {
        return Math.mulDiv(amount, totalSupply() + VIRTUAL_SHARES, latestAum + VIRTUAL_ASSETS);
    }

    function _convertToAssets(uint256 shares) private view returns (uint256) {
        return Math.mulDiv(shares, latestAum + VIRTUAL_ASSETS, totalSupply() + VIRTUAL_SHARES);
    }

    function _pricePerShare() private view returns (uint256) {
        return Math.mulDiv(latestAum + VIRTUAL_ASSETS, PPS_SCALE, totalSupply() + VIRTUAL_SHARES);
    }

    function _deviationBps(uint256 a, uint256 b) private pure returns (uint256) {
        if (b == 0) return type(uint256).max;
        uint256 diff = a > b ? a - b : b - a;
        return (diff * BPS_DENOMINATOR) / b;
    }

    // --- queue funding ---

    /// @dev USDT held in the contract that is not already earmarked to claimers.
    function _idleFundable() private view returns (uint256) {
        uint256 bal = asset.balanceOf(address(this));
        return bal > totalClaimable ? bal - totalClaimable : 0;
    }

    function _hasApprovedUnfunded() private view returns (bool) {
        // Liability-based, not queue-position-based: slots settled directly via
        // payApproved go stale in the queue but carry no outstanding value, and
        // they must not hold deposit surplus back from the strategy.
        return approvedOutstanding > 0;
    }

    /// @dev FIFO funding: credit `claimable` for the oldest approved requests until
    ///      the budget is spent or the iteration bound is hit. Pull-over-push only;
    ///      no external transfer here.
    function _fundQueue(uint256 budget, uint256 maxIterations) private returns (uint256 consumed) {
        uint256 iterations;
        while (consumed < budget && fundingHead < fundingTail && iterations < maxIterations) {
            iterations++;
            uint256 id = _fundingQueue[fundingHead];
            RedemptionRequest storage r = _requests[id];

            // Skip a slot whose request was already settled directly (payApproved):
            // it is no longer Approved, so drop it and move on.
            if (r.status != Status.Approved) {
                delete _fundingQueue[fundingHead];
                fundingHead++;
                continue;
            }

            uint256 take = Math.min(budget - consumed, r.outstanding);
            r.outstanding -= take;
            consumed += take;
            claimable[r.user] += take;
            totalClaimable += take;
            pendingRedemptionAum -= take;
            approvedOutstanding -= take;

            bool fullyFunded = r.outstanding == 0;
            if (fullyFunded) {
                r.status = Status.Funded;
                delete _fundingQueue[fundingHead]; // reclaim the consumed slot
                fundingHead++;
            }
            emit RedemptionFunded(id, r.user, take, fullyFunded);
        }
    }

    /// @dev Reserved storage for future versions; preserves layout across upgrades.
    uint256[50] private __gap;
}

// SPDX-License-Identifier: MIT
pragma solidity 0.8.19;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {ERC20Upgradeable} from "@openzeppelin/contracts-upgradeable/token/ERC20/ERC20Upgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import {PausableUpgradeable} from "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";

/// @title Nawa USDT Vault
/// @notice Share-based USDT yield vault. Capital is deployed off-chain into a
///         curated private-credit strategy; the contract is a non-custodial
///         router and escrow that holds funds only transiently under fixed rules.
///
///         Accounting is oracle-priced: an aumUpdater reports the off-chain
///         assets backing outstanding shares (`latestAum`). Value accrues to the
///         share price, not the balance, so the share token is a standard ERC20.
///
///         Redemptions are asynchronous: requestRedeem (burn) -> approve (set
///         final amount, enqueue) -> fund (from deposit netting or the backstop)
///         -> claim. A deposit nets its inflow against the oldest approved-unfunded
///         redemptions before forwarding the surplus to the strategy.
///
///         Deployed behind a UUPS proxy. Upgrades are gated to `upgrader`, which is
///         expected to be a TimelockController so an upgrade is announced on-chain
///         and delayed before it can take effect.
contract NawaUSDTVault is
    Initializable,
    ERC20Upgradeable,
    ReentrancyGuardUpgradeable,
    PausableUpgradeable,
    UUPSUpgradeable
{
    using SafeERC20 for IERC20;

    // --- constants ---

    /// @dev Price-per-share fixed-point scale, independent of token decimals.
    uint256 private constant PPS_SCALE = 1e18;

    /// @dev Virtual share/asset offset. Because `latestAum` is tracked in storage
    ///      (never read from `asset.balanceOf`), a direct USDT donation cannot move
    ///      the share price, so the classic ERC4626 inflation attack is structurally
    ///      blocked. The +1/+1 offset additionally hardens the first-deposit rounding.
    uint256 private constant VIRTUAL_SHARES = 1;
    uint256 private constant VIRTUAL_ASSETS = 1;

    uint256 private constant BPS_DENOMINATOR = 10_000;
    uint256 private constant MAX_AUM_CHANGE_LIMIT_BPS = 5_000; // 50%
    uint256 private constant MAX_AUM_UPDATE_COOLDOWN = 7 days;
    uint256 private constant MAX_SETTLEMENT_WINDOW = 180 days;
    uint256 private constant MAX_AUM_AGE = 30 days;
    uint256 private constant OUTFLOW_FREEZE_DURATION = 48 hours;
    uint256 private constant OVERRIDE_NAV_DEVIATION_CEILING_BPS = 1_000; // 10%

    uint8 private constant SHARE_DECIMALS = 6;

    // --- redemption queue ---

    enum Status {
        None,
        Pending,
        Approved,
        Funded,
        Rejected,
        Cancelled,
        Settled
    }

    struct RedemptionRequest {
        address user;
        uint256 shares; // shares burned for this request
        uint256 assetAmount; // current settlement payout (may be overridden at approval)
        uint256 outstanding; // assetAmount minus funded so far; 0 once fully funded
        uint256 originalPps; // price-per-share snapshot at request time (PPS_SCALE)
        uint256 overridePps; // 0 if no override applied
        uint256 requestedAt; // timestamp; basis for the settlement SLA
        uint256 cancelAfter; // deadline fixed at request time; a later window change cannot move it
        Status status;
    }

    // --- asset ---

    // Set once in initialize. Treat as upgrade-immutable: a future upgrade must
    // never add a setter, as repointing the asset would corrupt all accounting.
    IERC20 public asset;

    // --- roles ---

    address public admin; // Nawa, day-to-day operator
    address public pendingAdmin;
    address public fundsManagerAssigner; // multisig: the ONLY caller of setFundsManager
    address public fundsManager; // curator deployment address (receives surplus)
    address public redeemManager; // hot key: approves/rejects requests
    address public aumUpdater; // oracle: reports off-chain AUM
    address public pauser; // can pause but cannot move funds
    address public backstop; // multisig: funds the queue from recycled strategy liquidity
    address public upgrader; // authorized to upgrade the implementation (TimelockController)
    address public guardian; // multisig: can freeze outflows briefly in an incident

    // --- accounting ---

    uint256 public latestAum; // assets backing outstanding shares
    uint256 public pendingRedemptionAum; // assets committed to burned-but-unfunded redemptions
    uint256 public approvedOutstanding; // still-unfunded value across Approved requests
    uint256 public totalClaimable; // sum of unclaimed `claimable` balances
    uint256 public mintingCap; // max share totalSupply via deposits

    mapping(address => uint256) public claimable; // pull-over-push payout ledger

    // --- redemption queue state ---

    mapping(uint256 => RedemptionRequest) private _requests;
    uint256 public requestCounter; // next request id

    // Funding queue: a FIFO of *approved* request ids awaiting cash. Approval
    // enqueues; funding drains from the head. Keeping it separate from the request
    // log means an unapproved (Pending) request can never block funding of approved
    // ones behind it.
    mapping(uint256 => uint256) private _fundingQueue; // position => request id
    uint256 public fundingHead; // next position to fund
    uint256 public fundingTail; // next position to enqueue
    uint256 public maxNettingIterations; // gas bound on the funding loop

    // --- guardrails / limits ---

    uint256 public aumChangeLimitBps; // max per-share |delta| per AUM update
    uint256 public aumUpdateCooldownSecs; // min gap between AUM updates
    uint256 public lastAumUpdateAt;
    uint256 public lastNavAffectingBlock; // last block that changed supply or latestAum outside updateAum
    uint256 public maxAumAge; // max report age for price-sensitive entry/exit paths
    uint256 public outflowsFrozenUntil; // guardian circuit breaker on exit/funding paths
    uint256 public overrideNavMaxDeviationBps; // cap on approval override vs request-time NAV

    uint256 public minDeposit; // in asset units (6 decimals)
    uint256 public minRedeemShares; // in share units
    uint256 public maxSettlementWindow; // SLA: requests should be funded within this window

    // --- events ---

    event Deposited(address indexed user, uint256 assets, uint256 shares, uint256 forwardedToStrategy);
    event RedemptionRequested(uint256 indexed id, address indexed user, uint256 shares, uint256 assetAmount);
    event RedemptionApproved(
        uint256 indexed id, address indexed user, uint256 assetAmount, uint256 originalPps, uint256 overridePps
    );
    event RedemptionRejected(uint256 indexed id, address indexed user, uint256 shares);
    event RedemptionCancelled(uint256 indexed id, address indexed user, uint256 shares);
    event RedemptionSettled(uint256 indexed id, address indexed user, uint256 amount);
    event RedemptionFunded(uint256 indexed id, address indexed user, uint256 amount, bool fullyFunded);
    event Claimed(address indexed user, uint256 amount);
    /// @dev totalFunded counts everything credited to the queue in this call,
    ///      including idle balance that was already in the contract, so it can
    ///      legitimately exceed amountIn. Off-chain accounting of the backstop's
    ///      own contribution must sum amountIn, never totalFunded.
    event BackstopFunded(address indexed from, uint256 amountIn, uint256 totalFunded);
    event SurplusSwept(address indexed to, uint256 amount);
    event AumUpdated(uint256 oldAum, uint256 newAum, uint256 newPricePerShare);

    event FundsManagerChanged(address indexed previous, address indexed current);
    event FundsManagerAssignerChanged(address indexed previous, address indexed current);
    event RedeemManagerChanged(address indexed previous, address indexed current);
    event AumUpdaterChanged(address indexed previous, address indexed current);
    event PauserChanged(address indexed previous, address indexed current);
    event BackstopChanged(address indexed previous, address indexed current);
    event UpgraderChanged(address indexed previous, address indexed current);
    event GuardianChanged(address indexed previous, address indexed current);
    event OutflowsFrozen(address indexed by, uint256 until);
    event OutflowsUnfrozen(address indexed by);
    event SharesBurned(address indexed from, uint256 shares);
    event AdminTransferStarted(address indexed previous, address indexed pending);
    event AdminTransferred(address indexed previous, address indexed current);
    event ParameterChanged(bytes32 indexed key, uint256 value);

    // --- errors ---

    error NotAuthorized();
    error ZeroAddress();
    error ZeroAmount();
    error BelowMinimum();
    error MintingCapExceeded();
    error InvalidStatus();
    error CooldownActive();
    error ChangeLimitExceeded();
    error DeviationTooHigh();
    error ParameterOutOfRange();
    error FundsManagerUnset();
    error NothingToClaim();
    error AumUnderflow();
    error SettlementWindowNotElapsed();
    error WouldZeroAum();
    error RecoveryRequired();
    error StaleReport();
    error StaleNav();
    error PendingFullExit();
    error RepriceWhilePaused();
    error Expired();
    error SlippageExceeded();
    error OutflowFreezeActive();

    // --- modifiers ---

    modifier onlyAdmin() {
        if (msg.sender != admin) revert NotAuthorized();
        _;
    }

    modifier onlyRedeemManager() {
        if (msg.sender != redeemManager) revert NotAuthorized();
        _;
    }

    /// @dev Guardian circuit breaker on the paths that move USDT out or credit
    ///      claimable. Distinct from pause: pause is the soft halt that stops
    ///      entry and pricing while the queue winds down; this stops the wind-down
    ///      itself when something already credited money in error. Time-bounded so
    ///      it can never become a permanent freeze of user funds.
    modifier whenOutflowsNotFrozen() {
        if (block.timestamp < outflowsFrozenUntil) revert OutflowFreezeActive();
        _;
    }

    struct InitParams {
        IERC20 asset;
        address admin;
        address fundsManagerAssigner;
        address fundsManager;
        address redeemManager;
        address aumUpdater;
        address pauser;
        address backstop;
        address upgrader;
        address guardian;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(InitParams memory p) external initializer {
        if (
            address(p.asset) == address(0) ||
            p.admin == address(0) ||
            p.fundsManagerAssigner == address(0) ||
            p.redeemManager == address(0) ||
            p.aumUpdater == address(0) ||
            p.pauser == address(0) ||
            p.backstop == address(0) ||
            p.upgrader == address(0) ||
            p.guardian == address(0)
        ) revert ZeroAddress();

        __ERC20_init("Nawa USDT Vault", "nzUSDT");
        __ReentrancyGuard_init();
        __Pausable_init();
        __UUPSUpgradeable_init();

        asset = p.asset;
        admin = p.admin;
        fundsManagerAssigner = p.fundsManagerAssigner;
        fundsManager = p.fundsManager; // may be set later by the assigner
        redeemManager = p.redeemManager;
        aumUpdater = p.aumUpdater;
        pauser = p.pauser;
        backstop = p.backstop;
        upgrader = p.upgrader;
        guardian = p.guardian;

        // defaults
        aumChangeLimitBps = 200; // 2% per update
        aumUpdateCooldownSecs = 1 days;
        maxAumAge = 7 days;
        overrideNavMaxDeviationBps = 200; // 2%
        lastAumUpdateAt = block.timestamp;

        minDeposit = 100 * (10 ** SHARE_DECIMALS); // 100 USDT
        minRedeemShares = 1 * (10 ** SHARE_DECIMALS); // 1 share
        maxSettlementWindow = 120 days;
        maxNettingIterations = 50;
        mintingCap = type(uint256).max;

        // Log the initial configuration so indexers can rebuild role and
        // parameter history from events alone, not only from later changes.
        emit AdminTransferred(address(0), p.admin);
        emit FundsManagerAssignerChanged(address(0), p.fundsManagerAssigner);
        if (p.fundsManager != address(0)) emit FundsManagerChanged(address(0), p.fundsManager);
        emit RedeemManagerChanged(address(0), p.redeemManager);
        emit AumUpdaterChanged(address(0), p.aumUpdater);
        emit PauserChanged(address(0), p.pauser);
        emit BackstopChanged(address(0), p.backstop);
        emit UpgraderChanged(address(0), p.upgrader);
        emit GuardianChanged(address(0), p.guardian);
        emit ParameterChanged("aumChangeLimitBps", aumChangeLimitBps);
        emit ParameterChanged("aumUpdateCooldownSecs", aumUpdateCooldownSecs);
        emit ParameterChanged("maxAumAge", maxAumAge);
        emit ParameterChanged("overrideNavMaxDeviationBps", overrideNavMaxDeviationBps);
        emit ParameterChanged("minDeposit", minDeposit);
        emit ParameterChanged("minRedeemShares", minRedeemShares);
        emit ParameterChanged("maxSettlementWindow", maxSettlementWindow);
        emit ParameterChanged("maxNettingIterations", maxNettingIterations);
        emit ParameterChanged("mintingCap", mintingCap);
    }

    function decimals() public pure override returns (uint8) {
        return SHARE_DECIMALS;
    }

    /// @dev UUPS upgrade gate. `upgrader` is expected to be a TimelockController,
    ///      so an upgrade is queued publicly and can only execute after its delay.
    function _authorizeUpgrade(address) internal view override {
        if (msg.sender != upgrader) revert NotAuthorized();
    }

    // --- user flows ---

    /// @notice Deposit USDT, mint shares at the current price, net the inflow
    ///         against the oldest approved-unfunded redemptions, and forward the
    ///         surplus to the strategy. Executes at the stored NAV at inclusion
    ///         time, whatever it is; use depositWithMinShares to bound it.
    function deposit(uint256 amount) external nonReentrant whenNotPaused returns (uint256 shares) {
        shares = _deposit(amount);
    }

    /// @notice deposit with execution bounds: reverts if the transaction lands
    ///         after `deadline` or mints fewer than `minSharesOut`, so an oracle
    ///         update between signing and inclusion cannot worsen the fill.
    function depositWithMinShares(
        uint256 amount,
        uint256 minSharesOut,
        uint256 deadline
    ) external nonReentrant whenNotPaused returns (uint256 shares) {
        if (block.timestamp > deadline) revert Expired();
        shares = _deposit(amount);
        if (shares < minSharesOut) revert SlippageExceeded();
    }

    function _deposit(uint256 amount) private returns (uint256 shares) {
        if (amount < minDeposit) revert BelowMinimum();
        // An empty vault bootstraps at pps 1.0 with no price to protect, so a
        // stale report must not block it; the oracle may simply not be live yet.
        if (totalSupply() > 0 && block.timestamp > lastAumUpdateAt + maxAumAge) revert StaleNav();
        // Zero AUM with live shares is a corrupted pricing state (the guards in
        // requestRedeem, _applyOverride and updateAum keep it unreachable); refuse
        // to price against it rather than mint at a near-zero share price.
        if (latestAum == 0 && totalSupply() > 0) revert RecoveryRequired();
        // Do not bootstrap at pps 1.0 while a full-supply redemption is still
        // unsettled: a later reject or cancel re-mints those shares at their old
        // price and dilutes everyone who entered in between. Deposits reopen once
        // the exit is funded, settled, rejected or cancelled.
        if (totalSupply() == 0 && pendingRedemptionAum > 0) revert PendingFullExit();

        asset.safeTransferFrom(msg.sender, address(this), amount);

        // Price against pre-deposit state.
        shares = _convertToShares(amount);
        if (shares == 0) revert ZeroAmount();
        if (totalSupply() + shares > mintingCap) revert MintingCapExceeded();

        _mint(msg.sender, shares);
        latestAum += amount;
        lastNavAffectingBlock = block.number;

        // Fund the queue from this inflow (pull-over-push: credit claimable only).
        uint256 consumed = _fundQueue(amount, maxNettingIterations);
        uint256 surplus = amount - consumed;

        // Forward the surplus only when no approved request is still owed money.
        // If approved requests remain (the iteration bound stopped us short), keep
        // the surplus idle so processQueue can fund it, rather than shipping cash
        // owed to an exiting redeemer off-chain to the strategy.
        if (surplus > 0 && !_hasApprovedUnfunded()) {
            if (fundsManager == address(0)) revert FundsManagerUnset();
            asset.safeTransfer(fundsManager, surplus);
        } else {
            surplus = 0;
        }

        emit Deposited(msg.sender, amount, shares, surplus);
    }

    /// @notice Burn shares to queue a redemption. The payout is priced and locked
    ///         at request time; later NAV moves do not change it (approval may
    ///         still apply a bounded override). Executes at the stored NAV at
    ///         inclusion time; use requestRedeemWithMinAssets to bound it.
    function requestRedeem(uint256 shares) external nonReentrant whenNotPaused returns (uint256 id) {
        (id, ) = _requestRedeem(shares);
    }

    /// @notice requestRedeem with execution bounds on the locked amount: reverts
    ///         if the transaction lands after `deadline` or locks less than
    ///         `minAssetsOut`. The bound covers request-time pricing only; the
    ///         final payout can still move within the approval override cap.
    function requestRedeemWithMinAssets(
        uint256 shares,
        uint256 minAssetsOut,
        uint256 deadline
    ) external nonReentrant whenNotPaused returns (uint256 id) {
        if (block.timestamp > deadline) revert Expired();
        uint256 assetAmount;
        (id, assetAmount) = _requestRedeem(shares);
        if (assetAmount < minAssetsOut) revert SlippageExceeded();
    }

    function _requestRedeem(uint256 shares) private returns (uint256 id, uint256 assetAmount) {
        if (shares < minRedeemShares) revert BelowMinimum();
        if (block.timestamp > lastAumUpdateAt + maxAumAge) revert StaleNav();
        if (latestAum == 0 && totalSupply() > 0) revert RecoveryRequired();

        assetAmount = _convertToAssets(shares);
        if (assetAmount == 0) revert ZeroAmount();
        // A partial redemption must never drain latestAum to zero while shares
        // remain: that state skips the AUM change-limit and corrupts deposit
        // pricing. Rounding can push assetAmount up to the full latestAum in a
        // deep-loss book, so reject and let the user redeem in full instead.
        if (shares < totalSupply() && assetAmount >= latestAum) revert WouldZeroAum();
        uint256 pps = _pricePerShare();

        _burn(msg.sender, shares);

        latestAum -= assetAmount;
        pendingRedemptionAum += assetAmount;
        lastNavAffectingBlock = block.number;

        // When the last holder exits, clear the rounding dust so the vault
        // re-bootstraps at pps 1.0 on the next deposit.
        if (totalSupply() == 0) latestAum = 0;

        id = requestCounter++;
        _requests[id] = RedemptionRequest({
            user: msg.sender,
            shares: shares,
            assetAmount: assetAmount,
            outstanding: assetAmount,
            originalPps: pps,
            overridePps: 0,
            requestedAt: block.timestamp,
            cancelAfter: block.timestamp + maxSettlementWindow,
            status: Status.Pending
        });

        emit RedemptionRequested(id, msg.sender, shares, assetAmount);
    }

    /// @notice Pull your own accrued payout. Remains callable while paused so a halt
    ///         cannot trap funded redeemers; only the time-bounded guardian outflow
    ///         freeze can defer it.
    function claim() external nonReentrant whenOutflowsNotFrozen returns (uint256) {
        return _claim(msg.sender);
    }

    /// @notice Push a user's accrued payout to them. Permissionless: it can only ever
    ///         send `claimable[user]` to `user`, so a keeper (or anyone) can settle on
    ///         their behalf and the user never has to claim. Paying one user at a time
    ///         keeps a frozen recipient from blocking others.
    function claimFor(address user) external nonReentrant whenOutflowsNotFrozen returns (uint256) {
        return _claim(user);
    }

    function _claim(address user) private returns (uint256 amount) {
        amount = claimable[user];
        if (amount == 0) revert NothingToClaim();

        claimable[user] = 0;
        totalClaimable -= amount;

        asset.safeTransfer(user, amount);
        emit Claimed(user, amount);
    }

    /// @notice Permissionless. Push the funding queue forward using USDT already
    ///         idle in the contract (netting surplus left by the iteration bound,
    ///         or funds returned via the backstop).
    function processQueue(uint256 maxIterations) external nonReentrant whenOutflowsNotFrozen {
        uint256 available = _idleFundable();
        if (available == 0) return;
        _fundQueue(available, maxIterations);
    }

    // --- redeem manager ---

    /// @dev Optional re-pricing shared by approveRequest / approveAndPay. Moves the
    ///      difference between shareholders (latestAum) and the redemption liability
    ///      (pendingRedemptionAum), bounded by overrideNavMaxDeviationBps.
    function _applyOverride(RedemptionRequest storage r, uint256 overridePps) private {
        if (overridePps == 0 || overridePps == r.originalPps) return;
        // Approval stays callable while paused so the queue can wind down, but an
        // actual reprice moves latestAum, and with entry and exit frozen no holder
        // can react to it. Winding the queue down never requires moving the price.
        if (paused()) revert RepriceWhilePaused();
        if (_deviationBps(overridePps, r.originalPps) > overrideNavMaxDeviationBps) revert DeviationTooHigh();

        uint256 newAmount = Math.mulDiv(r.shares, overridePps, PPS_SCALE);
        if (newAmount == 0) revert ZeroAmount();

        uint256 oldAmount = r.assetAmount;
        if (newAmount > oldAmount) {
            uint256 delta = newAmount - oldAmount;
            // >=: an override must never drain latestAum to zero while shares
            // remain outstanding (see the invariant note in requestRedeem).
            if (delta >= latestAum) revert AumUnderflow();
            latestAum -= delta;
            pendingRedemptionAum += delta;
        } else if (newAmount < oldAmount) {
            uint256 delta = oldAmount - newAmount;
            latestAum += delta;
            pendingRedemptionAum -= delta;
            // A down-override on the last holder's exit returns value to a book
            // with no shareholders left. Clear it like the request path does, or
            // the orphaned amount would corrupt the next bootstrap price.
            if (totalSupply() == 0) latestAum = 0;
        }

        r.assetAmount = newAmount;
        r.outstanding = newAmount;
        r.overridePps = overridePps;
        lastNavAffectingBlock = block.number;
    }

    /// @notice Validate a request, finalise its payout, and enqueue it for funding
    ///         (deposit netting / backstop). Moves no cash. Callable while paused so
    ///         the backstop can wind down.
    /// @param overridePps optional corrected price-per-share (PPS_SCALE). 0 to keep
    ///        the request-time price. Bounded by overrideNavMaxDeviationBps.
    function approveRequest(uint256 id, uint256 overridePps) external onlyRedeemManager {
        RedemptionRequest storage r = _requests[id];
        if (r.status != Status.Pending) revert InvalidStatus();

        _applyOverride(r, overridePps);

        r.status = Status.Approved;
        approvedOutstanding += r.outstanding;
        _fundingQueue[fundingTail++] = id;

        emit RedemptionApproved(id, r.user, r.assetAmount, r.originalPps, r.overridePps);
    }

    /// @notice Approve and pay a Pending request directly in one step: the redeem
    ///         manager sends the exact payout to the user now, instead of routing it
    ///         through netting/backstop and a later claim. The caller funds it (from
    ///         recycled strategy liquidity) and must have approved the vault to pull
    ///         the payout. A frozen recipient only fails their own settlement.
    function approveAndPay(
        uint256 id,
        uint256 overridePps
    ) external onlyRedeemManager nonReentrant whenOutflowsNotFrozen {
        RedemptionRequest storage r = _requests[id];
        if (r.status != Status.Pending) revert InvalidStatus();

        _applyOverride(r, overridePps);

        uint256 payout = r.assetAmount;
        r.outstanding = 0;
        r.status = Status.Settled;
        pendingRedemptionAum -= payout;

        emit RedemptionApproved(id, r.user, payout, r.originalPps, r.overridePps);
        asset.safeTransferFrom(msg.sender, r.user, payout);
        emit RedemptionSettled(id, r.user, payout);
    }

    /// @notice Settle an already-Approved request directly, paying the caller's USDT
    ///         to the user for the still-outstanding amount (an approved request may
    ///         be partially funded already; the funded part stays claimable). No
    ///         re-price — the amount was finalized at approval. Its funding-queue slot
    ///         is left in place and lazily skipped by `_fundQueue` once settled.
    function payApproved(uint256 id) external onlyRedeemManager nonReentrant whenOutflowsNotFrozen {
        RedemptionRequest storage r = _requests[id];
        if (r.status != Status.Approved) revert InvalidStatus();

        uint256 payout = r.outstanding;
        if (payout == 0) revert ZeroAmount();
        r.outstanding = 0;
        r.status = Status.Settled;
        pendingRedemptionAum -= payout;
        approvedOutstanding -= payout;

        asset.safeTransferFrom(msg.sender, r.user, payout);
        emit RedemptionSettled(id, r.user, payout);
    }

    /// @notice Reject a still-Pending request, returning the user's shares and
    ///         reversing the request-time accounting. Re-mint intentionally bypasses
    ///         mintingCap: it reverses a prior burn, not a new subscription.
    function rejectRequest(uint256 id) external {
        if (msg.sender != redeemManager && msg.sender != admin) revert NotAuthorized();

        RedemptionRequest storage r = _requests[id];
        if (r.status != Status.Pending) revert InvalidStatus();

        r.status = Status.Rejected;
        r.outstanding = 0;
        latestAum += r.assetAmount;
        pendingRedemptionAum -= r.assetAmount;
        lastNavAffectingBlock = block.number;
        _mint(r.user, r.shares);

        emit RedemptionRejected(id, r.user, r.shares);
    }

    /// @notice User escape hatch: cancel your own still-Pending request once the
    ///         settlement window has elapsed, reclaiming your burned shares. Gives
    ///         redeemers on-chain recourse if the operator never approves. Only
    ///         Pending requests qualify (an approved request is already queued for
    ///         funding); the re-mint reverses a burn, so it bypasses mintingCap.
    function cancelRequest(uint256 id) external nonReentrant {
        RedemptionRequest storage r = _requests[id];
        if (r.user != msg.sender) revert NotAuthorized();
        if (r.status != Status.Pending) revert InvalidStatus();
        if (block.timestamp <= r.cancelAfter) revert SettlementWindowNotElapsed();

        r.status = Status.Cancelled;
        r.outstanding = 0;
        latestAum += r.assetAmount;
        pendingRedemptionAum -= r.assetAmount;
        lastNavAffectingBlock = block.number;
        _mint(r.user, r.shares);

        emit RedemptionCancelled(id, r.user, r.shares);
    }

    // --- backstop (multisig) ---

    /// @notice Pull recycled strategy liquidity into the contract and fund the
    ///         queue. The slow-path source when deposit inflow is insufficient.
    ///         Callable while paused for emergency wind-down, but subject to the
    ///         guardian outflow freeze.
    function fundFromBackstop(
        uint256 amount,
        uint256 maxIterations
    ) external nonReentrant whenOutflowsNotFrozen {
        if (msg.sender != backstop) revert NotAuthorized();
        if (amount == 0) revert ZeroAmount();

        asset.safeTransferFrom(msg.sender, address(this), amount);
        // Fund from the whole idle balance, not just this transfer: stranded
        // netting surplus should reach the queue in the same call.
        uint256 totalFunded = _fundQueue(_idleFundable(), maxIterations);

        emit BackstopFunded(msg.sender, amount, totalFunded);
    }

    // --- oracle (aumUpdater) ---

    /// @notice Report the off-chain assets backing outstanding shares, NET of any
    ///         performance fee and excluding pendingRedemptionAum. Fees are taken
    ///         off-chain before reporting; the contract charges no fee of its own.
    /// @param snapshotBlock the block whose on-chain state the report was computed
    ///        against. A deposit, redemption request, override, reject or cancel
    ///        landing after that block invalidates the report: the absolute value
    ///        would silently revert their accounting. Recompute and resubmit.
    function updateAum(uint256 newAum, uint256 snapshotBlock) external whenNotPaused {
        if (msg.sender != aumUpdater) revert NotAuthorized();
        if (block.timestamp < lastAumUpdateAt + aumUpdateCooldownSecs) revert CooldownActive();
        if (snapshotBlock > block.number || snapshotBlock < lastNavAffectingBlock) revert StaleReport();

        uint256 supply = totalSupply();
        uint256 oldAum = latestAum;

        // An empty vault backs nothing: force AUM to zero regardless of the report,
        // so no update can price an arbitrary bootstrap and the next deposit starts
        // at pps 1.0. The change-limit is meaningless with no shares. A zero report
        // is accepted here: zero is the true value of an empty vault.
        if (supply == 0) {
            latestAum = 0;
            lastAumUpdateAt = block.timestamp;
            emit AumUpdated(oldAum, 0, PPS_SCALE);
            return;
        }

        // With shares outstanding, a zero report cannot be priced through the
        // change-limit path; a true total loss is an incident handled by pause
        // and governance, not an ordinary oracle report.
        if (newAum == 0) revert ZeroAmount();

        // Zero AUM with live shares would let this report skip the change-limit
        // and set an arbitrary price. Unreachable while the request, override and
        // deposit guards hold; if it ever occurs, recovery goes through governance.
        if (oldAum == 0) revert RecoveryRequired();

        // Bound the per-share price move, not the raw AUM, so the cap is unaffected
        // by how much of the book is mid-redemption.
        uint256 oldPps = Math.mulDiv(oldAum + VIRTUAL_ASSETS, PPS_SCALE, supply + VIRTUAL_SHARES);
        // A price that floors to zero (supply vastly larger than AUM) cannot anchor
        // the deviation check; treat it like the zero-AUM state above.
        if (oldPps == 0) revert RecoveryRequired();
        uint256 candidatePps = Math.mulDiv(newAum + VIRTUAL_ASSETS, PPS_SCALE, supply + VIRTUAL_SHARES);
        if (_deviationBps(candidatePps, oldPps) > aumChangeLimitBps) revert ChangeLimitExceeded();

        latestAum = newAum;
        lastAumUpdateAt = block.timestamp;

        emit AumUpdated(oldAum, newAum, Math.mulDiv(newAum + VIRTUAL_ASSETS, PPS_SCALE, supply + VIRTUAL_SHARES));
    }

    // --- multisig: fundsManager ---

    /// @notice Set where deposit surplus is sent. Exclusive to the assigner
    ///         multisig; the Nawa admin cannot call this.
    function setFundsManager(address newFundsManager) external {
        if (msg.sender != fundsManagerAssigner) revert NotAuthorized();
        if (newFundsManager == address(0)) revert ZeroAddress();
        if (newFundsManager == fundsManager) return;
        emit FundsManagerChanged(fundsManager, newFundsManager);
        fundsManager = newFundsManager;
    }

    /// @notice Rotate the assigner. Only the current assigner can do this, so the
    ///         gate cannot be repointed by the admin.
    function setFundsManagerAssigner(address newAssigner) external {
        if (msg.sender != fundsManagerAssigner) revert NotAuthorized();
        if (newAssigner == address(0)) revert ZeroAddress();
        if (newAssigner == fundsManagerAssigner) return;
        emit FundsManagerAssignerChanged(fundsManagerAssigner, newAssigner);
        fundsManagerAssigner = newAssigner;
    }

    /// @notice Governance remedy for shares that exist in error (a bug, a bad
    ///         report, an operational mistake): burn them from the named holder so
    ///         the dilution of everyone else is reversed. Gated to `upgrader`, the
    ///         same timelock that controls upgrades, so use is announced on-chain
    ///         and delayed; it can never be a fast or quiet action.
    function burnSharesFrom(address from, uint256 shares) external {
        if (msg.sender != upgrader) revert NotAuthorized();
        _burn(from, shares);
        // If governance removes the last shares, nothing is backed anymore;
        // clear the book like a full exit so the next deposit boots at pps 1.0.
        if (totalSupply() == 0) latestAum = 0;
        lastNavAffectingBlock = block.number;
        emit SharesBurned(from, shares);
    }

    /// @notice Rotate the upgrade authority. Only the current upgrader can call it,
    ///         so the change is itself subject to the timelock delay. Used for key
    ///         rotation or repointing the proxy at a new authority.
    function setUpgrader(address newUpgrader) external {
        if (msg.sender != upgrader) revert NotAuthorized();
        if (newUpgrader == address(0)) revert ZeroAddress();
        if (newUpgrader == upgrader) return;
        emit UpgraderChanged(upgrader, newUpgrader);
        upgrader = newUpgrader;
    }

    // --- admin (Nawa) ---

    /// @notice Forward genuinely surplus idle USDT to the strategy. Cash needed to
    ///         cover in-flight redemptions is retained: the sendable amount is idle
    ///         minus the full redemption liability (`pendingRedemptionAum`), which
    ///         already counts every burned-share request, Pending or approved.
    function sweepToStrategy(uint256 amount) external onlyAdmin nonReentrant {
        if (fundsManager == address(0)) revert FundsManagerUnset();
        uint256 idle = _idleFundable();
        uint256 free = idle > pendingRedemptionAum ? idle - pendingRedemptionAum : 0;
        uint256 send = amount > free ? free : amount;
        if (send == 0) revert ZeroAmount();
        asset.safeTransfer(fundsManager, send);
        emit SurplusSwept(fundsManager, send);
    }

    function setRedeemManager(address a) external onlyAdmin {
        if (a == address(0)) revert ZeroAddress();
        if (a == redeemManager) return;
        emit RedeemManagerChanged(redeemManager, a);
        redeemManager = a;
    }

    function setAumUpdater(address a) external onlyAdmin {
        if (a == address(0)) revert ZeroAddress();
        if (a == aumUpdater) return;
        emit AumUpdaterChanged(aumUpdater, a);
        aumUpdater = a;
    }

    function setPauser(address a) external onlyAdmin {
        if (a == address(0)) revert ZeroAddress();
        if (a == pauser) return;
        emit PauserChanged(pauser, a);
        pauser = a;
    }

    function setBackstop(address a) external onlyAdmin {
        if (a == address(0)) revert ZeroAddress();
        if (a == backstop) return;
        emit BackstopChanged(backstop, a);
        backstop = a;
    }

    function setAumChangeLimitBps(uint256 v) external onlyAdmin {
        if (v == 0 || v > MAX_AUM_CHANGE_LIMIT_BPS) revert ParameterOutOfRange();
        if (v == aumChangeLimitBps) return;
        aumChangeLimitBps = v;
        emit ParameterChanged("aumChangeLimitBps", v);
    }

    function setAumUpdateCooldown(uint256 v) external onlyAdmin {
        if (v > MAX_AUM_UPDATE_COOLDOWN) revert ParameterOutOfRange();
        if (v == aumUpdateCooldownSecs) return;
        aumUpdateCooldownSecs = v;
        emit ParameterChanged("aumUpdateCooldownSecs", v);
    }

    function setOverrideNavMaxDeviationBps(uint256 v) external onlyAdmin {
        if (v > OVERRIDE_NAV_DEVIATION_CEILING_BPS) revert ParameterOutOfRange();
        if (v == overrideNavMaxDeviationBps) return;
        overrideNavMaxDeviationBps = v;
        emit ParameterChanged("overrideNavMaxDeviationBps", v);
    }

    function setMaxAumAge(uint256 v) external onlyAdmin {
        if (v == 0 || v > MAX_AUM_AGE) revert ParameterOutOfRange();
        if (v == maxAumAge) return;
        maxAumAge = v;
        emit ParameterChanged("maxAumAge", v);
    }

    function setMinDeposit(uint256 v) external onlyAdmin {
        if (v == minDeposit) return;
        minDeposit = v;
        emit ParameterChanged("minDeposit", v);
    }

    function setMinRedeemShares(uint256 v) external onlyAdmin {
        if (v == 0) revert ParameterOutOfRange();
        if (v == minRedeemShares) return;
        minRedeemShares = v;
        emit ParameterChanged("minRedeemShares", v);
    }

    function setMintingCap(uint256 v) external onlyAdmin {
        if (v == mintingCap) return;
        mintingCap = v;
        emit ParameterChanged("mintingCap", v);
    }

    function setMaxSettlementWindow(uint256 v) external onlyAdmin {
        // Bounded so admin can't disable the cancelRequest escape hatch by pushing the
        // window arbitrarily far out (or overflowing requestedAt + window).
        if (v == 0 || v > MAX_SETTLEMENT_WINDOW) revert ParameterOutOfRange();
        if (v == maxSettlementWindow) return;
        maxSettlementWindow = v;
        emit ParameterChanged("maxSettlementWindow", v);
    }

    function setMaxNettingIterations(uint256 v) external onlyAdmin {
        if (v == 0) revert ParameterOutOfRange();
        if (v == maxNettingIterations) return;
        maxNettingIterations = v;
        emit ParameterChanged("maxNettingIterations", v);
    }

    function transferAdmin(address newAdmin) external onlyAdmin {
        if (newAdmin == address(0)) revert ZeroAddress();
        pendingAdmin = newAdmin;
        emit AdminTransferStarted(admin, newAdmin);
    }

    function acceptAdmin() external {
        if (msg.sender != pendingAdmin) revert NotAuthorized();
        emit AdminTransferred(admin, pendingAdmin);
        admin = pendingAdmin;
        pendingAdmin = address(0);
    }

    // --- pause (pauser) ---

    function pause() external {
        if (msg.sender != pauser && msg.sender != admin) revert NotAuthorized();
        _pause();
    }

    function unpause() external onlyAdmin {
        _unpause();
    }

    // --- outflow freeze (guardian) ---

    /// @notice Freeze claim, funding and direct-settlement paths for a fixed
    ///         48 hours, the reaction window when claimable was credited in error
    ///         (bad report or bug) and money is about to leave. Calling again
    ///         extends the window; admin can rotate a misbehaving guardian and
    ///         unfreeze, so the breaker cannot be held down forever.
    function freezeOutflows() external {
        if (msg.sender != guardian) revert NotAuthorized();
        outflowsFrozenUntil = block.timestamp + OUTFLOW_FREEZE_DURATION;
        emit OutflowsFrozen(msg.sender, outflowsFrozenUntil);
    }

    /// @notice Lift the freeze early once the incident is understood.
    function unfreezeOutflows() external {
        if (msg.sender != guardian && msg.sender != admin) revert NotAuthorized();
        outflowsFrozenUntil = 0;
        emit OutflowsUnfrozen(msg.sender);
    }

    function setGuardian(address a) external onlyAdmin {
        if (a == address(0)) revert ZeroAddress();
        if (a == guardian) return;
        emit GuardianChanged(guardian, a);
        guardian = a;
    }

    // --- views ---

    function pricePerShare() external view returns (uint256) {
        return _pricePerShare();
    }

    function previewDeposit(uint256 amount) external view returns (uint256) {
        return _convertToShares(amount);
    }

    function previewRedeem(uint256 shares) external view returns (uint256) {
        return _convertToAssets(shares);
    }

    function getRequest(uint256 id) external view returns (RedemptionRequest memory) {
        return _requests[id];
    }

    /// @notice True once a request has been outstanding longer than the SLA window
    ///         that was in force when it was made.
    function isRequestOverdue(uint256 id) external view returns (bool) {
        RedemptionRequest storage r = _requests[id];
        if (r.status != Status.Pending && r.status != Status.Approved) return false;
        return block.timestamp > r.cancelAfter;
    }

    // --- internal math ---

    function _convertToShares(uint256 amount) private view returns (uint256) {
        return Math.mulDiv(amount, totalSupply() + VIRTUAL_SHARES, latestAum + VIRTUAL_ASSETS);
    }

    function _convertToAssets(uint256 shares) private view returns (uint256) {
        return Math.mulDiv(shares, latestAum + VIRTUAL_ASSETS, totalSupply() + VIRTUAL_SHARES);
    }

    function _pricePerShare() private view returns (uint256) {
        return Math.mulDiv(latestAum + VIRTUAL_ASSETS, PPS_SCALE, totalSupply() + VIRTUAL_SHARES);
    }

    function _deviationBps(uint256 a, uint256 b) private pure returns (uint256) {
        if (b == 0) return type(uint256).max;
        uint256 diff = a > b ? a - b : b - a;
        return (diff * BPS_DENOMINATOR) / b;
    }

    // --- queue funding ---

    /// @dev USDT held in the contract that is not already earmarked to claimers.
    function _idleFundable() private view returns (uint256) {
        uint256 bal = asset.balanceOf(address(this));
        return bal > totalClaimable ? bal - totalClaimable : 0;
    }

    function _hasApprovedUnfunded() private view returns (bool) {
        // Liability-based, not queue-position-based: slots settled directly via
        // payApproved go stale in the queue but carry no outstanding value, and
        // they must not hold deposit surplus back from the strategy.
        return approvedOutstanding > 0;
    }

    /// @dev FIFO funding: credit `claimable` for the oldest approved requests until
    ///      the budget is spent or the iteration bound is hit. Pull-over-push only;
    ///      no external transfer here.
    function _fundQueue(uint256 budget, uint256 maxIterations) private returns (uint256 consumed) {
        uint256 iterations;
        while (consumed < budget && fundingHead < fundingTail && iterations < maxIterations) {
            iterations++;
            uint256 id = _fundingQueue[fundingHead];
            RedemptionRequest storage r = _requests[id];

            // Skip a slot whose request was already settled directly (payApproved):
            // it is no longer Approved, so drop it and move on.
            if (r.status != Status.Approved) {
                delete _fundingQueue[fundingHead];
                fundingHead++;
                continue;
            }

            uint256 take = Math.min(budget - consumed, r.outstanding);
            r.outstanding -= take;
            consumed += take;
            claimable[r.user] += take;
            totalClaimable += take;
            pendingRedemptionAum -= take;
            approvedOutstanding -= take;

            bool fullyFunded = r.outstanding == 0;
            if (fullyFunded) {
                r.status = Status.Funded;
                delete _fundingQueue[fundingHead]; // reclaim the consumed slot
                fundingHead++;
            }
            emit RedemptionFunded(id, r.user, take, fullyFunded);
        }
    }

    /// @dev Reserved storage for future versions; preserves layout across upgrades.
    uint256[50] private __gap;
}

